async function doAction(action,id) {
  if(action==='close-modal')return closeModal();
  if(action==='theme'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('neuro-theme',theme);return;}
  if(action==='logout'){await saveNotes();await api('/logout',{});closeModal();return boot();}
  if(action==='settings')return settingsModal();
  if(action==='demo'){const d=await api('/demo',{});notify(d.message);return route();}
  if(action==='export'){const data=await api('/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='neurostudy-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Esportati dati e fonti. Conserva il file in un luogo protetto.');return;}
  if(action==='upload')return uploadModal();
  if(action==='update-doc')return uploadModal(id);
  if(action==='source')return sourceModal(id);
  if(action==='delete-doc'){if(!confirm('Eliminare il documento estratto? Le citazioni storiche nei quiz e nelle schede restano: elimina anche quei contenuti per rimuoverle.'))return;await api('/documents/'+id,undefined,'DELETE');return library();}
  if(action==='generate'||action==='generate-card')return generateModal([],{},action==='generate-card'?'card':'question');
  if(action==='regenerate-card'||action==='regenerate-question'){const kind=action==='regenerate-card'?'card':'question';const list=await api(kind==='card'?'/cards':'/questions');const item=list.find(i=>i.id===id);return generateModal([...new Set(item.sources.map(s=>s.document_id))],{},kind,id);}
  if(action==='quiz-start')return quizStartModal();
  if(action==='bookmark'){await api('/questions/'+id+'/bookmark',{});notify('Preferenza salvata');if(S.sessionKind==='quiz'&&location.hash.startsWith('#session/quiz')){const old=S.active.questions.find(q=>q.id===id);if(old)old.bookmarked=!old.bookmarked;renderQuiz();}else await quizBank();return;}
  if(action==='edit-question'){S.questions=await api('/questions');return questionEdit(S.questions.find(q=>q.id===id));}
  if(action==='delete-question'||action==='delete-card'){if(!confirm('Eliminare il contenuto? I quiz già avviati conservano la propria copia.'))return;await api((action==='delete-card'?'/cards/':'/questions/')+id,undefined,'DELETE');return action==='delete-card'?cardBank():quizBank();}
  if(action==='report-question'||action==='report-case'){const kind=action==='report-case'?'case':'question';modal('Segnala un problema',`<form id="report-form" data-id="${h(id)}" data-kind="${kind}"><label>Descrivi l’errore o il percorso non riconosciuto<textarea name="text" minlength="5" maxlength="5000" required></textarea></label><p class="muted">La segnalazione viene conservata nel database e nell’esportazione. Nessun invio automatico a un docente o servizio esterno.</p><button type="submit" class="primary">Salva segnalazione</button></form>`);return;}
  if(action==='question-card'){S.questions=await api('/questions');const q=S.questions.find(q=>q.id===id)||S.active?.questions?.find(q=>q.id===id);if(!q)throw Error('Domanda originale eliminata');return cardEdit({},q);}
  if(action==='quiz-next'||action==='quiz-prev'){S.index+=action==='quiz-next'?1:-1;return renderQuiz();}
  if(action==='quiz-finish'){if(!confirm('Concludere la sessione? Le domande non risposte restano tali e non possono più essere compilate.'))return;S.active=await api('/quizzes/'+S.active.id+'/finish',{});return renderQuiz();}
  if(action==='new-card')return cardEdit();
  if(action==='edit-card'){S.cards=await api('/cards');return cardEdit(S.cards.find(c=>c.id===id));}
  if(action==='suspend-card'){const c=(await api('/cards')).find(c=>c.id===id);await api('/cards/'+id,{...c,suspended:!c.suspended},'PUT');return cardBank();}
  if(action==='review-start')return reviewStartModal();
  if(action==='reveal'){S.active=await api(`/reviews/${S.active.id}/reveal/${id}`,{});return renderReview();}
  if(action.startsWith('rate-')){S.active=await api(`/reviews/${S.active.id}/rate`,{card_id:id,grade:action.slice(5)});return renderReview();}
  if(action==='case-action'){await saveNotes();S.active=await api(`/cases/${S.active.id}/actions`,{action:id});return renderCase();}
  if(action==='hint'){await saveNotes();S.active=await api(`/cases/${S.active.id}/hint`,{});return renderCase();}
  if(action==='case-conclude'){await saveNotes();return concludeModal();}
  if(action==='score-explain')return modal('Comprendere la valutazione',`<p>${h(S.active.assessment.explanation)}</p><div class="notice warn">${h(S.active.assessment.limits)}</div>`);
  if(action==='related-quiz'||action==='related-cards'){location.hash=action==='related-quiz'?'#quiz':'#cards';S.searchAfter=id;return;}
}
document.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action]');if(!button)return;
  const wasDisabled=button.disabled;button.disabled=true;
  try{await doAction(button.dataset.action,button.dataset.id);if(button.tagName==='A'&&button.hash===location.hash&&button.dataset.action==='close-modal')await route();}catch(err){notify(err.message);}finally{button.disabled=wasDisabled;}
});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target;const f=formData(form);const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
  try {
    if(form.id==='login-form'){await api('/status');await api('/login',{password:f.password});return boot();}
    if(form.id==='upload-form'){await api('/documents',new FormData(form));closeModal();notify('Testo estratto e salvato. Controlla gli avvisi del documento.');await library();}
    if(form.id==='source-generate-form'){const selected=[...new FormData(form).getAll('section')];if(!selected.length)throw Error('Seleziona almeno una sezione');return generateModal([form.dataset.id],{[form.dataset.id]:selected});}
    if(form.id==='generate-form'){
      const ids=new FormData(form).getAll('document_ids');if(!ids.length)throw Error('Seleziona almeno un documento');
      const result=await api('/generate',{document_ids:ids,sections:S.generateSections||{},kind:f.kind,count:Number(f.count),difficulty:f.difficulty,engine:f.engine,replace_id:form.dataset.replace||null});
      if(form.dataset.replace&&result.items.length)await api((f.kind==='card'?'/cards/':'/questions/')+form.dataset.replace,undefined,'DELETE');
      modal('Generazione completata',`<p><strong>${result.items.length} contenuti salvati nel database.</strong></p>${result.warnings.map(w=>`<div class="notice warn">${h(w)}</div>`).join('')}<p>Puoi modificarli e approvarli nella banca prima di usarli.</p><a class="btn primary" href="#${f.kind==='card'?'cards':'quiz'}" data-action="close-modal">Apri i contenuti</a>`);
    }
    if(form.id==='quiz-start-form'){const q=await api('/quizzes',{count:Number(f.count),difficulty:f.difficulty,filter:f.filter,mode:f.mode,minutes:Number(f.minutes),topics:f.topic?[f.topic]:[],document_ids:f.document_id?[f.document_id]:[],include_demo:!!f.include_demo,include_review:!!f.include_review});closeModal();location.hash=`#session/quiz/${q.id}`;}
    if(form.id==='answer-form'){const selected=new FormData(form).getAll('selected').map(Number);if(!selected.length)throw Error('Seleziona almeno una risposta');S.active=await api('/quizzes/'+S.active.id+'/answer',{question_id:S.active.questions[S.index].id,selected});renderQuiz();}
    if(form.id==='question-edit-form'){await api('/questions/'+form.dataset.id,{...f,correct:f.correct.split(',').map(s=>Number(s.trim())-1),options:f.options.split('\n').map(s=>s.trim()).filter(Boolean),option_explanations:f.option_explanations.split('\n').map(s=>s.trim()).filter(Boolean),review_required:!!f.review_required},'PUT');closeModal();await quizBank();notify('Revisione salvata');}
    if(form.id==='card-edit-form'){const body={...f,suspended:f.suspended==='true',review_required:!!f.review_required,question_id:f.question_id||null};await api('/cards'+(form.dataset.id?'/'+form.dataset.id:''),body,form.dataset.id?'PUT':'POST');closeModal();notify('Flashcard salvata');if(!location.hash.startsWith('#session'))await cardBank();}
    if(form.id==='review-start-form'){const r=await api('/reviews',{topic:f.topic,document_id:f.document_id,include_demo:!!f.include_demo,include_review:!!f.include_review});closeModal();location.hash=`#session/review/${r.id}`;}
    if(form.id==='case-start-form'){const c=await api('/cases',{...f,minutes:Number(f.minutes)});location.hash=`#session/case/${c.id}`;}
    if(form.id==='case-text-form'){await saveNotes();S.active=await api('/cases/'+S.active.id+'/actions',{text:f.text});const input=$('#case-text-form textarea');if(input&&input.value===f.text)input.value='';renderCase();}
    if(form.id==='case-conclude-form'){S.active=await api('/cases/'+S.active.id+'/finish',f);closeModal();renderAssessment();}
    if(form.id==='settings-form'){await api('/settings',{daily_limit:Number(f.daily_limit),daily_goal:Number(f.daily_goal)},'PUT');closeModal();notify('Preferenze salvate');await route();}
    if(form.id==='report-form'){await api('/reports',{kind:form.dataset.kind,target_id:form.dataset.id,text:f.text});closeModal();notify('Segnalazione salvata per revisione ed esportazione');}
  } catch(err){notify(err.message);if(form.id==='login-form')$('#login-error').textContent=err.message;}
  finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',e=>{
  if(e.target.id==='bank-search'){const term=e.target.value.toLowerCase();document.querySelectorAll('.searchable').forEach(el=>el.hidden=!el.dataset.search.includes(term));}
  if(e.target.id==='action-search'){const term=e.target.value.toLowerCase();document.querySelectorAll('#case-actions button').forEach(el=>el.hidden=!el.dataset.search.includes(term));}
  if(e.target.id==='case-notes'){if($('#note-status'))$('#note-status').textContent='Salvataggio in corso…';clearTimeout(S.noteTimer);S.noteTimer=setTimeout(()=>saveNotes().catch(e=>notify(e.message)),600);}
});
window.addEventListener('hashchange',async()=>{try{await saveNotes();await route();if(S.searchAfter&&$('#bank-search')){$('#bank-search').value=S.searchAfter;$('#bank-search').dispatchEvent(new Event('input',{bubbles:true}));S.searchAfter=null;}}catch(e){notify(e.message);}});
document.documentElement.dataset.theme=localStorage.getItem('neuro-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
boot().catch(e=>{$('#login-view').textContent=e.message;});
